import {installControls,syncControls,bindControls,tierControls} from './phase3-ui.js';
import {installEconomics,syncEconomics,renderEconomics,bindEconomics} from './economics-ui.js';
import {referenceProject,referencePhoto} from './reference-pack.js';
import {DisplayScene} from './scene.js';
import {preset,pallet,styles,newSku,plan,surfaces,referenceNotes,fitTierCount} from './plan.js';
import {fresh,validateProject} from './project.js';
import {readImage,cropImage,readModel,download,persist,restore,backupProject,previousProject} from './assets.js';
import {buyerSheet,escapeHTML as esc} from './exports.js';
const $=id=>document.getElementById(id);
installControls();
installEconomics();
$('viewport').insertAdjacentHTML('beforeend','<div id="merchandiseWarning" class="merchandiseWarning" role="status" hidden></div>');
let exportInProgress=false;
let project=fresh(),activeSku=project.catalog[0].id,engine=null,result=null,revision=0,view='iso',showDimensions=true,saveTimer,assetBusy=false;
const config=()=>project.templates[project.type],sku=()=>project.catalog.find(p=>p.id===activeSku);
const toast=msg=>{$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),5000);};
function persistSoon(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{try{validateProject(structuredClone(project));}catch{$('saveStatus').textContent='Not saved · resolve invalid fields';return;}persist(project).then(()=>{$('saveStatus').textContent='Saved on this device';}).catch(()=>{$('saveStatus').textContent='Device storage unavailable · download project';});},500);}
function skuForm(){const p=sku();$('skuSelect').innerHTML=project.catalog.map(p=>`<option value="${esc(p.id)}">${esc(p.sku)} · ${esc(p.name)}</option>`).join('');$('skuSelect').value=p?.id||'';$('skuEditor').hidden=!p;if(!p)return;
 for(const [id,key] of Object.entries({pw:'w',pd:'d',ph:'h',skuCode:'sku',skuName:'name',representation:'representation',stackCount:'stackCount',productColor:'color'}))$(id).value=p[key]??'';
 $('rotate').checked=p.rotate;$('stackable').checked=p.stackable;$('stackable').disabled=p.representation!=='box';$('stackCount').disabled=!p.stackable||p.representation!=='box';$('modelUpload').hidden=p.representation!=='model';$('uploadLabel').textContent=p.art?'Replace SKU photograph':'Add SKU photograph';$('removeArt').hidden=!p.art;$('imageTools').hidden=!p.original||p.representation==='reference';$('art').disabled=p.representation==='reference';$('removeArt').hidden=!p.art||p.representation==='reference';$('referenceInfo').hidden=p.representation!=='reference';$('originalPreview').src=p.original||'';$('processedPreview').src=p.art||'';
 const crop=p.crop||{x:0,y:0,w:100,h:100,mask:false,tolerance:25};for(const k of ['x','y','w','h','tolerance'])$(`crop-${k}`).value=crop[k];$('maskWhite').checked=crop.mask;$('modelLabel').textContent=p.model?'Model loaded · replace':'Upload GLB / GLTF';syncEconomics(p,project);
}
function assignmentFeedback(){for(const row of $('assignments').querySelectorAll('[data-slot]')){const g=result?.groups?.find(g=>g.id===row.dataset.slot);row.querySelector('[data-count]').textContent=`${g?.total??0} / ${g?.capacity??0} · ${g?.cols??0} across × ${g?.rows??0} deep × ${g?.stacks??1} high`;const issue=row.querySelector('.assignmentIssue');issue.hidden=!g?.issue;issue.querySelector('[data-issue]').textContent=g?.issue??'';row.querySelector('[data-show-slot]').hidden=!row.querySelector('[data-field="sku"]').value;issue.querySelector('[data-auto-slot]').hidden=g?.kind!=='limits';const fit=issue.querySelector('[data-fit-tiers]');fit.hidden=!g?.issue||!result?.suggestedTiers;fit.textContent=`Use ${result?.suggestedTiers??''} tiers · equal spacing`;}}
function assignments(){if($('assignments').contains(document.activeElement)){assignmentFeedback();return;}const s=config(),r=surfaces(s);$('assignments').innerHTML=r.surfaces.map(x=>{const a=s.slots[x.id]||{};return `<div class="assignment" data-slot="${x.id}"><span>${x.face?esc(x.face)+' · ':''}Tier ${x.tier+1}${s.dividers?` · ${String.fromCharCode(65+x.comp)}`:''}<small>${x.w.toFixed(2)} × ${x.d.toFixed(2)} in</small></span><label>SKU<select data-field="sku" aria-label="Tier ${x.tier+1} compartment ${x.comp+1} SKU"><option value="">Empty</option>${project.catalog.map(p=>`<option value="${esc(p.id)}" ${a.sku===p.id?'selected':''}>${esc(p.sku)}</option>`).join('')}</select><button type="button" data-show-slot>Show in 3D</button></label><label>Facings<input data-field="facings" type="number" min="1" placeholder="Auto" value="${a.facings??''}" aria-label="${x.id} facings"></label><label>Deep<input data-field="rows" type="number" min="1" placeholder="Auto" value="${a.rows??''}" aria-label="${x.id} units deep"></label><label>Units<input data-field="qty" type="number" min="0" placeholder="Fill" value="${a.qty??''}" aria-label="${x.id} units"></label><small data-count></small><div class="assignmentIssue" hidden><span data-issue></span><button type="button" data-edit-sku="${esc(a.sku??'')}">Edit this SKU</button><button type="button" data-fit-tiers hidden></button><button type="button" data-auto-slot hidden>Use automatic facings / rows / units</button></div></div>`;}).join('');assignmentFeedback();}
function tierForm(){tierControls(config());}
function sync(){const s=config();for(const k of ['width','depth','height','levels','lip','header','board','base','gap'])$(k).value=s[k];$('name').value=project.name;$('color').value=s.color;$('dividers').checked=s.dividers;$('sign').checked=s.sign;$('risers').value=s.risers||0;$('compartments').value=s.compartments||2;for(const k of ['levels','base','header'])$(k).disabled=!pallet(s.type);$('risers').disabled=s.type!=='tray';$('shelfClass').disabled=pallet(s.type);$('shelfClass').value=[29.5,35.5,47.5].includes(s.width)?String(s.width):'custom';document.querySelectorAll('[data-type]').forEach(b=>{const a=b.dataset.type===project.type;b.classList.toggle('active',a);b.setAttribute('aria-pressed',a);});syncControls(s);skuForm();tierForm();}
function stats(r){const s=config();document.body.classList.toggle('invalid',!r.valid);$('conceptTitle').textContent=project.name||'Untitled retail concept';$('dimensionLabel').textContent=`${s.width}″ W × ${s.depth}″ D × ${s.height}″ H`;$('total').textContent=r.total.toLocaleString();$('layout').textContent=r.unused.toLocaleString();$('util').textContent=`${r.util.toFixed(1)}%`;$('opening').textContent=r.surfaces.length?`${Math.min(...r.surfaces.map(x=>x.clear)).toFixed(2)}″`:'—';$('usable').textContent=`${(s.width-2*s.board).toFixed(2)} × ${(s.depth-2*s.board).toFixed(2)} in`;$('remaining').textContent=`${r.capacity} assigned positions`;$('fitText').textContent=r.valid?`${r.total} units placed across ${Object.keys(r.counts).length} SKUs. ${r.unused} assigned positions remain unfilled.`:r.issues.join(' ');$('fitBadge').textContent=r.valid?'GEOMETRY FITS':'CHECK CONFIGURATION';$('merchandiseWarning').hidden=r.valid;$('merchandiseWarning').textContent=r.valid?'':`${r.previewable?'Preview shows only products that fit. ':''}${r.issues[0]??'Check the configuration.'}`;const notes=referenceNotes(s);$('guideNotes').textContent=(notes.length?notes.join(' '):'Reference dimensions match.')+' 2017 Canada reference defaults only; not current Walmart US approval. '+(pallet(s.type)?'Shipping excludes the optional header. Sign is a blank placeholder.':'Confirm shelf width, loaded weight, stability, and shipping case.');$('skuSummary').innerHTML=project.catalog.map(p=>`<span>${esc(p.sku)} <b>${r.counts[p.id]||0}</b></span>`).join('');renderEconomics(project,r,sku());assignments();}
async function refresh(){const rev=++revision;const snapshot=structuredClone(project);result=plan(config(),project.catalog);if(!result.valid)result.suggestedTiers=fitTierCount(config(),project.catalog);stats(result);$('status').textContent=engine?'Loading scene…':'3D unavailable';$('status').classList.add('loading');$('png').disabled=true;$('export').disabled=true;if(engine)engine.ready=false;persistSoon();if(!engine)return;try{await engine.update(snapshot.templates[snapshot.type],plan(snapshot.templates[snapshot.type],snapshot.catalog),snapshot.catalog,snapshot.branding);if(rev!==revision)return;engine.ready=result.valid&&!assetBusy;$('status').textContent=result.valid?'● Scene ready':result.previewable?'● Partial preview · check assignments':'● Check dimensions';$('status').classList.remove('loading');$('png').disabled=!engine.ready;$('export').disabled=!engine.ready;$('renderError').hidden=true;}catch(e){if(rev!==revision)return;$('status').textContent='Scene error';$('renderError').hidden=false;$('renderError').textContent=e.message;toast('Scene could not finish: '+e.message);}}
async function changeTemplate(type){if(engine)engine.faceAngle=0;project.type=type;if(!project.templates[type]){const s=preset(type),id=project.catalog[0]?.id;const r=surfaces(s);if(id)s.slots=Object.fromEntries(r.surfaces.map(x=>[x.id,{sku:id,qty:null,facings:null}]));project.templates[type]=s;}sync();await refresh();}
for(const k of ['width','depth','height','levels','lip','header','board','base','gap'])$(k).onchange=()=>{config()[k]=$(k).value===''?NaN:Number($(k).value);if(['levels','depth','height','header','base','board'].includes(k)){config().tierHeights=[];config().tierDepths=[];tierForm();}refresh();};
for(const [id,key] of Object.entries({pw:'w',pd:'d',ph:'h',skuCode:'sku',skuName:'name',representation:'representation',stackCount:'stackCount',productColor:'color'}))$(id).onchange=async()=>{const p=sku();if(!p)return;const previous=p[key];p[key]=['w','d','h','stackCount','price','cost'].includes(key)?($(id).value===''?(['price','cost'].includes(key)?null:NaN):Number($(id).value)):$(id).value;if(key==='representation'&&p.representation==='reference'){return withAsset(async()=>{try{p.art=await referencePhoto();p.stackable=false;p.stackCount=1;}catch(e){p.representation=previous;throw e;}});}if(key==='representation'&&p.representation!=='box'){p.stackable=false;p.stackCount=1;}skuForm();refresh();};
$('rotate').onchange=()=>{if(sku())sku().rotate=$('rotate').checked;refresh();};$('stackable').onchange=()=>{if(sku())sku().stackable=$('stackable').checked;skuForm();refresh();};$('name').oninput=()=>{project.name=$('name').value;$('conceptTitle').textContent=project.name;persistSoon();};$('color').oninput=()=>{config().color=$('color').value;refresh();};
$('skuSelect').onchange=()=>{activeSku=$('skuSelect').value;skuForm();};$('addSku').onclick=()=>{if(project.catalog.length>=24)return toast('Catalog limit: 24 SKUs.');const p=newSku(crypto.randomUUID());p.sku=`SKU-${project.catalog.length+1}`;project.catalog.push(p);activeSku=p.id;skuForm();refresh();};$('deleteSku').onclick=()=>{const p=sku();if(!p)return;project.catalog=project.catalog.filter(x=>x.id!==p.id);for(const s of Object.values(project.templates))for(const [id,a] of Object.entries(s.slots))if(a.sku===p.id)delete s.slots[id];activeSku=project.catalog[0]?.id;skuForm();refresh();};
document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>changeTemplate(b.dataset.type));document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));if(engine)engine.faceAngle=0;engine?.frame(view);});$('dimensions').onclick=()=>{showDimensions=!showDimensions;$('dimensionLabel').hidden=!showDimensions;$('dimensions').setAttribute('aria-pressed',showDimensions);};
$('compartments').oninput=()=>{config().compartments=Number($('compartments').value);config().dividers=true;$('dividers').checked=true;refresh();};$('dividers').onchange=()=>{config().dividers=$('dividers').checked;refresh();};$('sign').onchange=()=>{config().sign=$('sign').checked;refresh();};$('risers').onchange=()=>{config().risers=Number($('risers').value);config().tierHeights=[];config().tierDepths=[];tierForm();refresh();};$('shelfClass').onchange=()=>{if($('shelfClass').value==='custom')return;config().width=Number($('shelfClass').value);sync();refresh();};
$('tierLayout').onchange=e=>{const el=e.target;if(!el.dataset.axis)return;const s=config(),els=[...$('tierLayout').querySelectorAll(`[data-axis="${el.dataset.axis}"]`)];const axis=el.dataset.axis,key=axis==='height'?'tierHeights':axis==='depth'?'tierDepths':'shelfDepths';s[key]=els.map((x,i)=>{if(x.value!=='')return Number(x.value);const zones=surfaces({...s,shelfDepths:[]}).surfaces.filter(z=>z.tier===i);return s.type.startsWith('end')?s.depth:Math.min(...zones.map(z=>z.d));});refresh();};
$('assignments').onchange=e=>{const field=e.target.dataset.field,id=e.target.closest('[data-slot]')?.dataset.slot;if(!field||!id)return;const a=config().slots[id]||{sku:'',qty:null,facings:null};a[field]=field==='sku'?e.target.value:(e.target.value===''?null:Number(e.target.value));if(field==='sku'){a.qty=null;a.facings=null;a.rows=null;}config().slots[id]=a;refresh();};
$('emptyDisplay').onclick=()=>{config().slots={};refresh();};$('fillDisplay').onclick=()=>{if(!sku())return toast('Add a SKU first.');config().slots=Object.fromEntries(surfaces(config()).surfaces.map(x=>[x.id,{sku:sku().id,qty:null,facings:null}]));refresh();};
async function withAsset(action){if(assetBusy)return toast('Wait for the current upload to finish.');assetBusy=true;$('status').textContent='Loading assets…';for(const id of ['art','model','brandArt'])$(id).disabled=true;if(engine)engine.ready=false;$('png').disabled=$('export').disabled=true;try{await action();}catch(e){toast(e.message);}finally{assetBusy=false;for(const id of ['art','model','brandArt'])$(id).disabled=false;skuForm();await refresh();}}
$('art').onchange=e=>{const f=e.target.files[0],p=sku();if(!f||!p)return;withAsset(async()=>{const original=await readImage(f),crop={x:0,y:0,w:100,h:100,mask:false,tolerance:25},art=await cropImage(original,crop);p.original=original;p.crop=crop;p.art=art;toast('Photograph attached to '+p.sku+'. Crop or mask its background below.');});e.target.value='';};
$('applyCrop').onclick=()=>{const p=sku();if(!p?.original)return;withAsset(async()=>{const crop=Object.fromEntries(['x','y','w','h','tolerance'].map(k=>[k,Number($(`crop-${k}`).value)]));crop.mask=$('maskWhite').checked;const art=await cropImage(p.original,crop);p.crop=crop;p.art=art;toast('Crop/mask applied. Review the processed preview.');});};$('removeArt').onclick=()=>{const p=sku();if(p){p.art=null;p.original=null;}skuForm();refresh();};
$('model').onchange=e=>{const p=sku(),f=e.target.files[0];if(!f||!p)return;withAsset(async()=>{const data=await readModel(f);if(!engine)throw Error('WebGL is required to validate a model.');await engine.assets.model(data);p.model=data;toast('Model loaded and fitted within SKU dimensions.');});e.target.value='';};
$('brandArt').onchange=e=>{const f=e.target.files[0],surface=$('brandSurface').value;if(!f)return;withAsset(async()=>{project.branding[surface]=await cropImage(await readImage(f),{x:0,y:0,w:100,h:100,mask:false,tolerance:0});toast('Artwork added to '+surface+'.');});e.target.value='';};$('removeBrand').onclick=()=>{project.branding[$('brandSurface').value]=null;refresh();};
$('reset').onclick=()=>{project=fresh();activeSku=project.catalog[0].id;sync();refresh();toast('New blank concept. Download projects before resetting to keep earlier work.');};
$('save').onclick=()=>{try{validateProject(structuredClone(project));download(new Blob([JSON.stringify(project)],{type:'application/json'}),'display-studio-project-v2.json');}catch(e){toast('Project not saved: '+e.message);}};
$('project').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100*1024*1024)throw Error('Project limit is 100 MB.');const next=validateProject(JSON.parse(await f.text()));if(engine)await engine.assets.prepare(next.catalog,next.branding);project=next;activeSku=next.catalog[0]?.id;sync();await refresh();toast('Project opened with SKU assets and all template allocations.');}catch(e){toast(e.message);}finally{e.target.value='';}};
async function capture(){if(!result.valid||!engine?.ready)throw Error('Resolve warnings and wait for the scene to finish loading.');return engine.png(Number($('resolution').value),$('exportView').value==='current'?view:$('exportView').value,$('transparent').checked,$('exportEnvironment').value);}
$('png').onclick=async()=>{try{await lockExport(async()=>{const blob=await capture();download(blob,`${project.type}-${$('exportView').value}-${$('resolution').value}.png`);toast('PNG exported at '+$('resolution').value+' × '+$('resolution').value+'.');});}catch(e){toast(e.message);}};
$('export').onclick=async()=>{try{await lockExport(async()=>{if(!engine?.ready||!result.valid)throw Error('Wait for a valid, complete scene.');const image=await engine.png(2048,view,false);download(await buyerSheet(project,result,image),'buyer-concept.html');toast('Buyer sheet downloaded. Open to print or save as PDF.');});}catch(e){toast(e.message);}};
// Input events keep calculations in sync during typing as well as on blur.
for(const k of ['width','depth','height','levels','lip','header','board','base','gap'])$(k).oninput=$(k).onchange;
for(const [id,key] of Object.entries({pw:'w',pd:'d',ph:'h',skuCode:'sku',skuName:'name',stackCount:'stackCount',productColor:'color'}))$(id).oninput=()=>{const p=sku();if(!p)return;p[key]=['w','d','h','stackCount','price','cost'].includes(key)?($(id).value===''?(['price','cost'].includes(key)?null:NaN):Number($(id).value)):$(id).value;const option=$('skuSelect').selectedOptions[0];if(option)option.textContent=p.sku+' · '+p.name;refresh();};
$('assignments').oninput=$('assignments').onchange;
$('assignments').onclick=e=>{const edit=e.target.closest('[data-edit-sku]'),fit=e.target.closest('[data-fit-tiers]'),show=e.target.closest('[data-show-slot]'),auto=e.target.closest('[data-auto-slot]');if(auto){const id=auto.closest('[data-slot]').dataset.slot,a=config().slots[id];if(a){a.facings=null;a.rows=null;a.qty=null;refresh();toast('This zone now uses its calculated capacity. SKU dimensions were kept.');}}else if(show){const id=show.closest('[data-slot]').dataset.slot,surf=surfaces(config()).surfaces.find(x=>x.id===id);if(surf&&engine){view='iso';engine.showFace(surf.angle||0);document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view==='iso'));$('viewport').scrollIntoView({block:'center',behavior:'smooth'});}}else if(edit){activeSku=edit.dataset.editSku;skuForm();$('ph').focus();$('ph').scrollIntoView({block:'center',behavior:'smooth'});}else if(fit){const n=fitTierCount(config(),project.catalog);if(!n)return;config().levels=n;config().tierHeights=[];sync();refresh();toast(`Using ${n} tiers with equal spacing. SKU dimensions and saved assignments were kept.`);}};
$('tierLayout').oninput=$('tierLayout').onchange;
$('assignments').addEventListener('focusout',()=>setTimeout(assignments,0));
$('referenceDemo').onclick=()=>{if(project.name==='Reference merchandise · open toy pack'&&project.catalog.length===1&&project.catalog[0].representation==='reference')return toast('Reference merchandise is already open.');withAsset(async()=>{await backupProject(project);project=await referenceProject();activeSku=project.catalog[0].id;$('restoreConcept').hidden=false;sync();toast('Showing the reference kit in all nine displays. Your earlier concept is backed up.');});};
$('restoreConcept').onclick=()=>withAsset(async()=>{const before=await previousProject();if(!before)throw Error('No previous concept is stored.');project=validateProject(before);activeSku=project.catalog[0]?.id;sync();toast('Previous concept restored.');});

$('skuSearch').oninput=()=>{const q=$('skuSearch').value.trim().toLowerCase();for(const option of $('skuSelect').options)option.hidden=!option.textContent.toLowerCase().includes(q);};
bindControls(config,refresh,sync,()=>engine);
bindEconomics(()=>project,sku,()=>result,persistSoon,toast);
try{engine=new DisplayScene($('stage'));}catch(e){$('status').textContent='WebGL unavailable';$('renderError').hidden=false;$('renderError').textContent='3D requires WebGL 2 and hardware acceleration. Try a current Chrome, Edge, Firefox, or Safari browser. The SKU catalog and calculator remain available.';console.error(e);}
try{const saved=await restore();if(saved){project=validateProject(saved);activeSku=project.catalog[0]?.id;}else{project=await referenceProject();activeSku=project.catalog[0].id;}if(saved&&project.name==='Phase 2 · three-SKU acceptance concept'&&project.catalog.some(p=>p.sku==='PNG-QA')){await backupProject(project);project=await referenceProject();activeSku=project.catalog[0].id;$('restoreConcept').hidden=false;}else $('restoreConcept').hidden=!(await previousProject());}catch(e){toast('Reference preview could not load; your saved concept remains on this device.');}
sync();await refresh();


async function lockExport(action){if(exportInProgress)throw Error('An export is already in progress.');exportInProgress=true;const fields=[...document.querySelectorAll('button,input,select')].map(el=>[el,el.disabled]);const status=$('status').textContent;for(const [el] of fields)el.disabled=true;$('status').textContent='Exporting image…';try{return await action();}finally{for(const [el,disabled] of fields)el.disabled=disabled;$('status').textContent=status;exportInProgress=false;}}
